// The unit circle: the four axis intercepts are the quadrantal angles, and the
// four interior marks are the 30-60-90 and 45-45-90 positions.
size(321,317);
draw((-1.22,0)--(1.22,0), gray(0.55));
draw((0,-1.22)--(0,1.22), gray(0.55));
draw(unitcircle);
label("$0$", (1.1,0), E);
label("$\frac{\pi}{2}$", (0,1.12), N);
label("$\pi$", (-1.12,0), W);
label("$\frac{3\pi}{2}$", (0,-1.12), S);
dot(dir(0), black+2pt);
dot(dir(pi/6), black+2pt);
dot(dir(pi/3), black+2pt);
dot(dir(pi/2), black+2pt);
dot(dir(2*pi/3), black+2pt);
dot(dir(pi), black+2pt);
label("$\frac{\pi}{6}$", dir(pi/6)*1.22, NE);
label("$\frac{\pi}{3}$", dir(pi/3)*1.22, NE);
label("$\frac{2\pi}{3}$", dir(2*pi/3)*1.22, NW);
label("$\frac{4\pi}{3}$", dir(4*pi/3)*1.22, SW);
label("$\frac{5\pi}{3}$", dir(5*pi/3)*1.22, SE);

// The 30-60-90 triangle inside the unit circle. Short leg 1, long leg
// sqrt(3), hypotenuse 2, so normalizing the hypotenuse to 1 gives 1/2 and
// sqrt(3)/2 directly.
size(183,201);
draw(unitcircle, gray(0.7));
pair O = (0,0);
pair A = (1,0);
pair B = (1,sqrt(3));
draw(O--A--B--cycle, black);
draw(O--B, dashed);
label("$O$", O, SW);
label("$A$", A, SE);
label("$B$", B, NE);
label("$1$", (O+A)/2, S);
label("$\sqrt{3}$", (A+B)/2, E);
label("$2$", (O+B)/2, NW);
label("$60^\circ$", (O+A)/2+(0,0.24), N);
label("$30^\circ$", (A+B)/2+(0.34,0), E);
label("$90^\circ$", A+(-0.24,0.12), NW);

// A full turn measured two ways: the outer labels are degrees, the inner
// labels are radians, and the marked point is the 60 degree position, which
// is also the pi over 3 position.
size(289,241);
draw(unitcircle);
draw((-1.25,0)--(1.25,0), gray(0.6));
draw((0,-1.25)--(0,1.25), gray(0.6));
label("$360^\circ$", dir(7*pi/6)*1.34, SW);
label("$2\pi$", dir(11*pi/6)*1.34, SE);
label("$0^\circ$", (1.3,0), E);
label("$90^\circ$", (-0.1,1.32), N);
label("$\frac{\pi}{2}$", (0.42,1.3), E);
label("$180^\circ$", (-1.32,0), W);
label("$270^\circ$", (0.1,-1.32), S);
label("$\pi$", (-0.98,-0.3), SW);
label("$\frac{3\pi}{2}$", (0.98,-0.3), SE);
dot(dir(pi/3), black+2pt);
label("$60^\circ = \frac{\pi}{3}$", dir(pi/3)*1.36, NE);

