// The 45-45-90 triangle inside the unit circle. Both legs are sqrt(2)/2
// and the hypotenuse is the radius, so the 45 degree values fall out of the
// leg over the hypotenuse ratio directly.
size(281,243);
draw(unitcircle, gray(0.7));
pair O = (0,0);
pair A = (1,0);
pair B = dir(pi/4);
draw(O--A--B--cycle, black);
draw(O--B, dashed);
label("$O$", O, SW);
label("$A$", A, SE);
label("$B$", B, NE);
label("$\frac{\sqrt{2}}{2}$", (O+A)/2, S);
label("$\frac{\sqrt{2}}{2}$", (A+B)/2, E);
label("$1$", (O+B)/2, NW);
label("$45^\circ$", B*1.24, N);
label("$45^\circ$", (0.8,0.8), SW);
label("$90^\circ$", A+(-0.22,0.14), NW);

// A sector of a circle of radius r with central angle theta. The arc is swept
// counterclockwise from the positive x-axis and the sector is the shaded
// wedge, so the two formulas read off the same picture.
size(241,241);
pair O=(0,0);
draw(scale(2)*unitcircle, gray(0.6));
fill((0,0)--(2,0)..(0,2)--cycle, gray(0.88));
draw((0,0)--(2,0), black);
draw((0,0)--(0,2), black);
label("$r$", (1,0), S);
label("$r$", (0,1), W);
label("$\theta$", (0.44,0.16), NE);
label("$O$", (0,0), SW);
label("$s = r\theta$", (1.35,0.85), E);
label("$\frac{1}{2}r^2\theta$", (0.8,-0.38), SE);
